\choiceTF
{ Biết ${x}$ thỏa mãn $\sqrt[3]{- 2 x - 5}=-1$. Khi đó: $x>0$ }
   { Biết $\sqrt[3]{x}-a=0$. Khi đó $x^3+1=a-1$ }
     { $\sqrt[3]{-64}.\sqrt[3]{-1} - \sqrt[3]{0}=6$ }
    { $\sqrt[3]{1000}=12$ }
\loigiai{
a) Khẳng định đã cho là khẳng định sai.\\
$\sqrt[3]{- 2 x - 5}=-1\Rightarrow - 4 x=-1\Rightarrow -4x=-1\Rightarrow x=-2$.\\
b) Khẳng định đã cho là khẳng định sai.\\
$\sqrt[3]{x}=a \Rightarrow x^3+1=a+1$.\\
c) Khẳng định đã cho là khẳng định sai.\\
$\sqrt[3]{-64}.\sqrt[3]{-1} - \sqrt[3]{0}=4$\\
d) Khẳng định đã cho là khẳng định sai.\\
$\sqrt[3]{1000}=10$.
}\end{ex}

